#!/usr/bin/env python3
"""Verify the optional 5-digit hand with 3-phalanx fingers (model/hand5_3seg, generated by build_finger_models.py).

Runs the same checks as Demo/AHSimulation/five_finger/verify_5f_model.py (imported, unchanged) so the
numbers compare 1:1 with reports/verify_AH_Right_5F.txt of the stock 5-digit hand:
structure, pinky = exact copy of the ring finger, stability sweeps, finger-to-finger and
finger-to-palm interference on a 9 x 9 grid per digit (all 6561 pose pairs per finger pair).
Added: each 3-phalanx finger of the hand moves exactly like the standalone finger model, and the demo
poses re-mapped to the new straight pose (f = -56 instead of -37.5) for stability and contacts.

Also: the 5-digit palm/back shells and grip pads (cad/five_finger/stl) against the new fingers, which curl
further than the stock ones (method of five_finger/check_shells.py).

Writes reports/verify_hand5_3seg.txt.  Usage: python verify_3seg_hand.py [--grid 9] [--shell-grid 13] [--only-shells]
"""

import argparse
import contextlib
import json
import sys

import mujoco
import numpy as np

from finger_common import CAD_DIR, DESIGN_JSON, HERE, MODEL_DIR, REPORT_DIR, Finger, three_seg_roles

sys.path.insert(0, str(HERE.parent / "five_finger"))
import verify_5f_model as V  # noqa: E402

THREE_SEG = ("index", "middle", "ring", "pinky")
F_STRAIGHT_STOCK = -37.5


def remap(pose, f_s):
    """Stock demo command (m1, m2) -> the same intent for a 3-phalanx finger: flexion rescaled from
    [stock straight, +90] to [new straight, +90] (hyperextension kept as an offset, never past the stop
    at f_s - 4), abduction kept but limited by the servo range |a| + |f| <= 90."""
    m1, m2 = pose
    a, f = (m1 + m2) / 2, (m1 - m2) / 2
    if f >= F_STRAIGHT_STOCK:
        f2 = f_s + (f - F_STRAIGHT_STOCK) * (90 - f_s) / (90 - F_STRAIGHT_STOCK)
    else:
        f2 = max(f_s + (f - F_STRAIGHT_STOCK), f_s - 4)
    a2 = float(np.clip(a, -(90 - abs(f2)), 90 - abs(f2)))
    return round(a2 + f2, 1), round(a2 - f2, 1)


class Tee:
    def __init__(self, *streams):
        self.streams = streams

    def write(self, s):
        for st in self.streams:
            st.write(s)

    def flush(self):
        for st in self.streams:
            st.flush()


def check_vs_single(h, f_s):
    """Each converted finger, in its own finger frame, against the standalone 3-phalanx model."""
    single = Finger(MODEL_DIR / "scene_3seg.xml", three_seg_roles())
    worst = 0.0
    tips = dict(index="tip1", middle="tip2", ring="tip3", pinky="tip5")
    for c in [(f_s, -f_s), (0, 0), (60, -60), (90, -90), (-20, 40), (30, 80)]:
        c = np.radians(c)
        h.reset()
        for dig in THREE_SEG:
            h.d.ctrl[h.ctrl[dig]] = c
        for _ in range(750):
            mujoco.mj_step(h.m, h.d)
        single.reset()
        single.move(*c, ramp=0.5, hold=1.0, check=False)
        ref = ref_in_geom_frame(single)  # both models: tip in the compiled finger_frame_1 geom frame
        for dig in THREE_SEG:
            p, R = V.base_frame(h, dig)
            worst = max(worst, np.linalg.norm(R.T @ (h.d.site(tips[dig]).xpos - p) - ref))
    V.log(f"== 2b. every 3-phalanx finger of the hand vs the standalone finger model (tip in its own finger frame, "
          f"6 commands): max difference {worst * 1e3:.4f} mm")


def ref_in_geom_frame(single):
    """Tip of the standalone model in the compiled finger_frame_1 geom frame (what V.base_frame uses)."""
    m, d = single.m, single.d
    g = next(i for i in range(m.ngeom) if m.geom_bodyid[i] == 1 and m.geom_dataid[i] >= 0 and
             mujoco.mj_id2name(m, mujoco.mjtObj.mjOBJ_MESH, m.geom_dataid[i]) == "finger_frame_1")
    p, R = d.geom_xpos[g], d.geom_xmat[g].reshape(3, 3)
    return R.T @ (d.site_xpos[single.tip] - p)


def shell_set(which):
    import check_shells as CS
    if which == "5f":
        return CS.shells("5f", "R")
    out = CAD_DIR / "stl" / "palm_shells"  # written by regen_palm_shells.py
    return {"palm_shell": out / "R-Palm_Shell_5F.stl", "top_shell": out / "R-Top_Shell_5F.stl",
            **{f"pad_{p.stem.split('_')[2].lower()}": p for p in sorted(out.glob("R-Palm_Pad_*_5F.stl"))}}


def check_palm_shells(grid, which="5f", coarse=1.0, fine=0.3):
    """Same as five_finger/check_shells.py --shells 5f, on the 3-phalanx hand."""
    shells = shell_set(which)
    h = V.Hand(MODEL_DIR / "hand5_3seg", shells)
    mesh = lambda gs: [g for g in gs if h.m.geom_type[g] == mujoco.mjtGeom.mjGEOM_MESH]  # noqa: E731
    h.geoms = {k: (mesh(a), mesh(b)) for k, (a, b) in h.geoms.items()}
    coarse, fine = coarse * 1e-3, fine * 1e-3
    touch = 0.75 * fine
    V.log(f"== 7{'' if which == '5f' else 'b'}. palm/back shells and grip pads "
          f"({'the existing ones, cad/five_finger/stl' if which == '5f' else 'regenerated around the 3-phalanx fingers, cad/five_finger/three_segment/stl/palm_shells'})"
          f" vs every digit, {grid}x{grid} grid per digit (method of five_finger/check_shells.py)")
    poses, _ = V.settle_grid(h, np.linspace(-np.pi / 2, np.pi / 2, grid))
    keys = list(poses)
    names = list(shells)
    groups = {n: {sp: V.Group(h, [h.part_geom[n]], sp) for sp in (coarse, fine)} for n in names}
    mujoco.mj_kinematics(h.m, h.d)
    spose = {n: g[fine].poses(h.d) for n, g in groups.items()}
    for dig in h.digits:
        g = {sp: V.Group(h, h.geoms[dig][0], sp) for sp in (coarse, fine)}
        pa = V.posed(h, g[coarse], poses)
        for n, gs in groups.items():
            res = []
            for pp in pa:
                dist, who = V.group_distance(g[coarse], pp, gs[coarse], spose[n], 0.005)
                if touch <= dist < 0.003:
                    dist, who = V.group_distance(g[fine], pp, gs[fine], spose[n], dist + coarse)
                res.append((dist, who))
            i = int(np.argmin([r[0] for r in res]))
            hits = [keys[k] for k, r in enumerate(res) if r[0] < touch]
            V.log(f"  {dig:<6} vs {n:<10} min {res[i][0] * 1e3:5.2f} mm at {V.fmt_pose(keys[i])}"
                  + (f" [{V.geom_label(h, res[i][1][0])}]" if res[i][1] else "")
                  + f"; touching at {len(hits)}/{len(res)} poses"
                  + (f": {', '.join(V.fmt_pose(k) for k in hits[:8])}" if hits else ""))


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--grid", type=int, default=9)
    ap.add_argument("--coarse", type=float, default=1.0)
    ap.add_argument("--fine", type=float, default=0.3)
    ap.add_argument("--shell-grid", type=int, default=13)
    ap.add_argument("--only-shells", action="store_true")
    ap.add_argument("--shells", choices=["5f", "regen", "both"], default="both")
    args = ap.parse_args()
    f_s = json.loads(DESIGN_JSON.read_text())["drive"]["f_straight_deg"]
    report = REPORT_DIR / ("verify_hand5_3seg_shells.txt" if args.only_shells else "verify_hand5_3seg.txt")
    with open(report, "w") as fh, contextlib.redirect_stdout(Tee(sys.stdout, fh)):
        which = ["5f", "regen"] if args.shells == "both" else [args.shells]
        if args.only_shells:
            for w in which:
                check_palm_shells(args.shell_grid, w)
            return
        V.log("== 5-digit right hand with 3-phalanx index/middle/ring/pinky (thumb stock): model/hand5_3seg")
        V.log("   checks imported unchanged from Demo/AHSimulation/five_finger/verify_5f_model.py")
        h = V.Hand(MODEL_DIR / "hand5_3seg")
        # the new pin cylinders are not meshes: the mesh-sampling clearance code only takes meshes
        mesh = lambda gs: [g for g in gs if h.m.geom_type[g] == mujoco.mjtGeom.mjGEOM_MESH]  # noqa: E731
        h.geoms = {k: (mesh(a), mesh(b)) for k, (a, b) in h.geoms.items()}
        V.check_structure(h)
        V.check_copy(h)
        check_vs_single(h, f_s)
        poses = {name: {dig: (remap(c, f_s) if dig in THREE_SEG else c) for dig, c in pose.items()}
                 for name, pose in V.DEMO_POSES_5F.items()}
        V.log("   demo poses re-mapped for the 3-phalanx fingers (right hand, deg):")
        for name, pose in poses.items():
            V.log(f"     {name:<15} " + "  ".join(f"{dig} {c}" for dig, c in pose.items()))
        V.DEMO_POSES_5F = poses  # used by check_stability and check_demo_poses
        V.check_stability(h)
        V.check_interference(h, args.grid, args.coarse, args.fine)
        V.check_demo_poses(h, args.fine)
        for w in which:
            check_palm_shells(args.shell_grid, w)


if __name__ == "__main__":
    main()
